        "testata": "Il Sole 24 Ore",
        "lingua_originale": "it",
        "titolo_orig": "Impatto guerra Iran",
        "testo_it": "L'operazione militare USA-Israele contro l'Iran (iniziata il 28/02/2026) ha impatti economici globali, secondo il FMI.",
        "priorita": "Altissima",
        "id_gruppo": 22,
        "link": "https://lab24.ilsole24ore.com/guerra-iran-impatto-energia-gas-economia/",
        "orario": "10:05",
